package config

import (
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"gopkg.in/yaml.v3"
)

// preserveOIDCProviderNames restores the spelling of provider keys from YAML.
// Viper lowercases map keys during unmarshalling, including provider names used
// in authentication URLs and validation errors.
func preserveOIDCProviderNames(path string, cfg *Config) error {
	if !cfg.Authentication.Methods.OIDC.Enabled {
		return nil
	}

	switch strings.ToLower(filepath.Ext(path)) {
	case ".yaml", ".yml":
	default:
		return nil
	}

	data, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("reading OIDC provider names: %w", err)
	}

	var raw struct {
		Authentication struct {
			Methods struct {
				OIDC struct {
					Providers map[string]any `yaml:"providers"`
				} `yaml:"oidc"`
			} `yaml:"methods"`
		} `yaml:"authentication"`
	}
	if err := yaml.Unmarshal(data, &raw); err != nil {
		return fmt.Errorf("reading OIDC provider names: %w", err)
	}

	names := make([]string, 0, len(raw.Authentication.Methods.OIDC.Providers))
	for name := range raw.Authentication.Methods.OIDC.Providers {
		names = append(names, name)
	}
	slices.Sort(names)

	seen := make(map[string]string, len(names))
	for _, name := range names {
		normalized := strings.ToLower(name)
		if previous, ok := seen[normalized]; ok {
			return fmt.Errorf("OIDC provider keys %q and %q conflict when case is ignored", previous, name)
		}
		seen[normalized] = name
	}

	providers := cfg.Authentication.Methods.OIDC.Method.Providers
	if providers == nil && len(names) > 0 {
		providers = make(map[string]AuthenticationMethodOIDCProvider, len(names))
		cfg.Authentication.Methods.OIDC.Method.Providers = providers
	}
	for _, name := range names {
		normalized := strings.ToLower(name)
		provider := providers[normalized]
		delete(providers, normalized)
		providers[name] = provider
	}

	return nil
}

func (c *AuthenticationConfig) SessionEnabled() bool {
	var sessionEnabled bool
	for _, info := range c.Methods.AllMethods() {
		sessionEnabled = sessionEnabled || (info.Enabled && info.SessionCompatible)
	}

	return sessionEnabled
}

func (c *AuthenticationConfig) validate() error {
	var sessionEnabled bool

	for _, info := range c.Methods.AllMethods() {
		if err := info.validate(); err != nil {
			return err
		}

		sessionEnabled = sessionEnabled || (info.Enabled && info.SessionCompatible)
		if info.Cleanup == nil {
			continue
		}

		field := "authentication.method" + info.Name()
		if info.Cleanup.Interval <= 0 {
			return errFieldWrap(field+".cleanup.interval", errPositiveNonZeroDuration)
		}

		if info.Cleanup.GracePeriod <= 0 {
			return errFieldWrap(field+".cleanup.grace_period", errPositiveNonZeroDuration)
		}
	}

	// ensure that when a session compatible authentication method has been
	// enabled that the session cookie domain has been configured with a non
	// empty value.
	if sessionEnabled {
		if c.Session.Domain == "" {
			err := errFieldWrap("authentication.session.domain", errValidationRequired)
			return fmt.Errorf("when session compatible auth method enabled: %w", err)
		}

		host, err := getHostname(c.Session.Domain)
		if err != nil {
			return fmt.Errorf("invalid domain: %w", err)
		}

		// strip scheme and port from domain
		// domain cookies are not allowed to have a scheme or port
		// https://github.com/golang/go/issues/28297
		c.Session.Domain = host
	}

	return nil
}

func getHostname(rawurl string) (string, error) {
	if !strings.Contains(rawurl, "://") {
		rawurl = "http://" + rawurl
	}
	u, err := url.Parse(rawurl)

	metadata["providers"] = providers

	info.Metadata, _ = structpb.NewStruct(metadata)

	return info
}

func (a AuthenticationMethodOIDCConfig) validate() error {
	// Sort provider names so the first reported error is stable when multiple
	// providers are invalid.
	names := make([]string, 0, len(a.Providers))
	for name := range a.Providers {
		names = append(names, name)
	}
	slices.Sort(names)

	for _, name := range names {
		provider := a.Providers[name]
		if err := validateProviderFields(name, provider.ClientID, provider.ClientSecret, provider.RedirectAddress); err != nil {
			return err
		}
	}

	return nil
}

